WITH with_latest AS (SELECT s.id, s.category, s.cost, s.stock_qty, s.tags, latest.order_item_unit_price, latest.quantity FROM products s JOIN LATERAL (SELECT c.unit_price AS order_item_unit_price, c.quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) latest ON TRUE), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY cost, id) AS event_seq, NTILE(5) OVER (ORDER BY stock_qty DESC, id) AS stock_qty_bucket, CUME_DIST() OVER (PARTITION BY category ORDER BY stock_qty DESC NULLS LAST) AS stock_qty_cume_dist FROM with_latest), cleaned AS (SELECT id, category, cost, stock_qty, tags, quantity, stock_qty_bucket, stock_qty_cume_dist, CASE WHEN quantity >= 8 THEN 'High' WHEN quantity >= 3 THEN 'Medium' ELSE 'Low' END AS quantity_level, stock_qty_cume_dist * event_seq AS stock_qty_cume_dist_times_event_seq FROM scored WHERE order_item_unit_price BETWEEN 260 AND 290), with_windows AS (SELECT id, tags, quantity, quantity_level, LAG(stock_qty, 2, 0) OVER (PARTITION BY category ORDER BY stock_qty, id) AS prev_stock_qty, ROW_NUMBER() OVER (PARTITION BY category ORDER BY stock_qty_cume_dist DESC, id) AS seq_no, NTILE(10) OVER (PARTITION BY category ORDER BY stock_qty, id) AS stock_qty_bucket_2 FROM cleaned WHERE stock_qty_cume_dist_times_event_seq >= 61), metrics AS (SELECT *, DENSE_RANK() OVER (ORDER BY prev_stock_qty DESC NULLS LAST) AS prev_stock_qty_dense_rank, FIRST_VALUE(stock_qty_bucket_2) IGNORE NULLS OVER (ORDER BY seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_stock_qty_bucket_2, LEAD(quantity, 1) OVER (ORDER BY prev_stock_qty, id) AS next_quantity FROM with_windows), latest_match AS (SELECT s.id, s.tags, s.quantity, s.quantity_level, s.prev_stock_qty_dense_rank, s.first_known_stock_qty_bucket_2, s.next_quantity, x.order_item_quantity, x.order_item_unit_price FROM metrics s LEFT JOIN LATERAL (SELECT c.quantity AS order_item_quantity, c.unit_price AS order_item_unit_price FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN order_item_unit_price >= 340 THEN 'LARGE' ELSE 'SMALL' END AS order_item_unit_price_tier, COUNT(*) AS cnt, PERCENTILE_APPROX(next_quantity, ARRAY(0.25, 0.5, 0.75)) AS next_quantity_quartiles, AVG(first_known_stock_qty_bucket_2) AS avg_first_known_stock_qty_bucket_2 FROM latest_match GROUP BY CASE WHEN order_item_unit_price >= 340 THEN 'LARGE' ELSE 'SMALL' END HAVING avg_first_known_stock_qty_bucket_2 >= 0 ORDER BY cnt DESC NULLS LAST;
